function platformCall(string $base,string $token,string $path): array{$url=rtrim($base,'/').$path;$h=['Accept: application/json'];if($token)$h[]='X-Digiti-Service-Token: '.$token;if(function_exists('curl_init')){$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$h,CURLOPT_TIMEOUT=>5,CURLOPT_CONNECTTIMEOUT=>2]);$raw=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);$err=curl_error($c);curl_close($c);if($raw===false)return['ok'=>false,'message'=>$err];$d=json_decode((string)$raw,true);return is_array($d)?$d+['_http'=>$code]:['ok'=>false,'message'=>'Invalid response','_http'=>$code];}$ctx=stream_context_create(['http'=>['method'=>'GET','header'=>implode("\r\n",$h),'timeout'=>5,'ignore_errors'=>true]]);$raw=@file_get_contents($url,false,$ctx);$d=json_decode((string)$raw,true);return is_array($d)?$d:['ok'=>false,'message'=>'Platform unavailable'];}
