$checks['PHP >= 8.2']=version_compare(PHP_VERSION,'8.2.0','>=');$checks['PDO MySQL']=extension_loaded('pdo_mysql');$checks['JSON']=extension_loaded('json');$checks['Fileinfo']=extension_loaded('fileinfo');$checks['cURL or URL fopen']=extension_loaded('curl')||filter_var(ini_get('allow_url_fopen'),FILTER_VALIDATE_BOOLEAN);$checks['Storage writable']=is_writable($root.'/storage');$checks['Imagick recommended']=class_exists('Imagick');$checks['RabbitMQ client dependency']=class_exists('PhpAmqpLib\\Connection\\AMQPStreamConnection');
