t'],'port'=>(int)$v['rabbit_port'],'username'=>$v['rabbit_user'],'password'=>(string)($_POST['rabbit_pass']??''),'vhost'=>$v['rabbit_vhost'],'connection_timeout'=>3.0,'read_write_timeout'=>70.0,'heartbeat'=>30,'keepalive'=>true,'confirm_timeout'=>5.0,'exchange'=>'epaper.jobs','dead_exchange'=>'epaper.dead','dead_queue'=>'epaper.dead','retry_exchange_prefix'=>'epaper.retry.','queues'=>['render'=>'epaper.render','assets'=>'epaper.assets','ocr'=>'epaper.ocr','finalize'=>'epaper.finalize']]]],true).";\n";if(file_put_contents($root.'/config/config.php',$config)===false)throw new RuntimeException('Could not write config/config.php');file_put_contents($lock,json_encode(['installed_at'=>gmdate('c'),'version'=>trim(file_get_contents($root.'/VERSION'))],JSON_PRETTY_PRINT));$done=true;}catch(Throwable$e){$errors[]='Install: '.$e->getMessage();}}
